#!/usr/bin/env node
/*
 * Builds a fully self-contained copy of the tool:
 *   index.html + locale files + i18n runtime + app.js
 *   -> bookmark-recovery.html
 *
 * The generated file has no external script/style/image dependencies and can
 * be opened directly from disk (file://) or copied to another computer.
 */
'use strict';

const fs = require('fs');
const path = require('path');

const root = __dirname;
const source = path.join(root, 'index.html');
const target = path.join(root, 'bookmark-recovery.html');
const scriptTag = /^([ \t]*)<script src="([^"]+)"><\/script>[ \t]*$/gm;

let html = fs.readFileSync(source, 'utf8');
const inlined = [];

html = html.replace(scriptTag, function (match, indent, src) {
	const file = path.join(root, src);
	const code = fs.readFileSync(file, 'utf8').replace(/<\/script/gi, '<\\/script');
	inlined.push(src);
	return indent + '<script>\n' + code + '\n' + indent + '</script>';
});

if (inlined.length === 0) {
	throw new Error('No <script src="..."> tags found in index.html');
}

const banner = '<!-- Standalone build generated by build-standalone.js. Edit index.html, app.js and i18n/ instead. -->\n';
html = html.replace('<!DOCTYPE html>\n', '<!DOCTYPE html>\n' + banner);

fs.writeFileSync(target, html);
console.log('Wrote ' + path.relative(process.cwd(), target) +
	' (' + (Buffer.byteLength(html) / 1024).toFixed(1) + ' KiB, ' +
	inlined.length + ' scripts inlined).');
